{
  "incident_detected": true,
  "root_cause_hypothesis": "An Android national-ID document-processing regression began with release 5.27 on 2025-11-10, increasing doc_unreadable rejections. The problem persists through 2025-12-15 and is also visible on 5.28; the warehouse supports a release-linked regression, but does not identify the exact implementation defect.",
  "supporting_metrics": [
    {
      "name": "overall KYC decision approval rate",
      "baseline_value": 0.892006,
      "anomaly_value": 0.825128,
      "unit": "fraction",
      "sql": "SELECT CASE WHEN decision_date < DATE '2025-11-10' THEN 'baseline' ELSE 'recent' END period, sum(n_decisions) decisions, sum(n_approved)::DOUBLE/sum(n_decisions) rate FROM agg_kyc_daily WHERE decision_date BETWEEN DATE '2025-09-01' AND DATE '2025-12-15' GROUP BY 1"
    },
    {
      "name": "android national_id KYC approval rate",
      "baseline_value": 0.88809,
      "anomaly_value": 0.692246,
      "unit": "fraction",
      "sql": "SELECT CASE WHEN decision_date < DATE '2025-11-10' THEN 'baseline' ELSE 'recent' END period, sum(n_approved)::DOUBLE/sum(n_decisions) rate FROM agg_kyc_daily WHERE decision_date BETWEEN DATE '2025-09-01' AND DATE '2025-12-15' AND platform='android' AND doc_type='national_id' GROUP BY 1"
    },
    {
      "name": "other platform-document slices KYC approval rate",
      "baseline_value": 0.894158,
      "anomaly_value": 0.897408,
      "unit": "fraction",
      "sql": "SELECT CASE WHEN decision_date < DATE '2025-11-10' THEN 'baseline' ELSE 'recent' END period, sum(n_approved)::DOUBLE/sum(n_decisions) rate FROM agg_kyc_daily WHERE decision_date BETWEEN DATE '2025-09-01' AND DATE '2025-12-15' AND NOT(platform='android' AND doc_type='national_id') GROUP BY 1"
    },
    {
      "name": "android national_id changepoint maximum log-likelihood ratio versus detection threshold",
      "baseline_value": 25.0,
      "anomaly_value": 307.1,
      "unit": "log-likelihood ratio",
      "sql": "calculate_uplift_or_stats({\"metric_slice\":{\"analysis\":\"kyc_changepoint\",\"platform\":\"android\",\"doc_type\":\"national_id\",\"channel\":null,\"segment_by\":null,\"k_a\":null,\"n_a\":null,\"k_b\":null,\"n_b\":null}})"
    },
    {
      "name": "android national_id doc_unreadable share of rejections, October versus November 2025",
      "baseline_value": 0.334802,
      "anomaly_value": 0.719368,
      "unit": "fraction",
      "sql": "SELECT month, reject_reason, sum(n_rejections) rejections, sum(n_rejections)::DOUBLE / sum(sum(n_rejections)) OVER (PARTITION BY month) rejection_share FROM agg_kyc_reject_reasons_monthly WHERE platform='android' AND doc_type='national_id' AND month BETWEEN DATE '2025-09-01' AND DATE '2025-12-01' GROUP BY 1,2 ORDER BY 1,2"
    }
  ],
  "recommended_action": "ROLLBACK_RELEASE",
  "reasoning_summary": "KYC decision approval fell from 0.892006 during September 1–November 9 to 0.825128 during November 10–December 15. Android national-ID approval fell from 0.88809 to 0.692246 while other slices stayed stable at 0.894158 versus 0.897408; the changepoint score of 307.1 exceeds the 25.0 detection threshold, ruling out ordinary variation. The break coincides with Android 5.27 on November 10, and doc_unreadable rose from 0.334802 to 0.719368 of this slice's rejections between October and November. Roll back the affected Android document-processing path to a verified pre-regression version, validate approval recovery, and help rejected users retry."
}
